const restoreProduct = `-- name: RestoreProduct :execrows
UPDATE products SET deleted_at = NULL, updated_at = now()
WHERE slug = $1 AND deleted_at IS NOT NULL
`

func (q *Queries) RestoreProduct(ctx context.Context, slug string) (int64, error) {
	result, err := q.db.Exec(ctx, restoreProduct, slug)
	if err != nil {
		return 0, err
	}
	return result.RowsAffected(), nil
}

const updateProductType = `-- name: UpdateProductType :one
UPDATE product_types SET
    label = COALESCE($1, label),
    icon = CASE WHEN 'icon' = ANY($2::text[]) THEN NULL ELSE COALESCE($3, icon) END,
    is_enabled = COALESCE($4, is_enabled),
    config = COALESCE($5, config),
    updated_at = now()
WHERE slug = $6
RETURNING id, slug, label, icon, is_enabled, config
`

type UpdateProductTypeParams struct {
	Label       *string  `json:"label"`
	ClearFields []string `json:"clear_fields"`
	Icon        *string  `json:"icon"`
	IsEnabled   *bool    `json:"is_enabled"`
	Config      []byte   `json:"config"`
	Slug        string   `json:"slug"`
}

type UpdateProductTypeRow struct {
	ID        pgtype.UUID `json:"id"`
	Slug      string      `json:"slug"`
	Label     string      `json:"label"`
	Icon      *string     `json:"icon"`
	IsEnabled bool        `json:"is_enabled"`
	Config    []byte      `json:"config"`
}

func (q *Queries) UpdateProductType(ctx context.Context, arg UpdateProductTypeParams) (UpdateProductTypeRow, error) {
	row := q.db.QueryRow(ctx, updateProductType,
		arg.Label,
		arg.ClearFields,
		arg.Icon,
		arg.IsEnabled,
		arg.Config,
		arg.Slug,
	)
	var i UpdateProductTypeRow
	err := row.Scan(
		&i.ID,
		&i.Slug,
		&i.Label,
		&i.Icon,
		&i.IsEnabled,
		&i.Config,
	)
	return i, err
}

